package com.nutritionplatform.nutritionprofile.controller;
import com.nutritionplatform.nutritionprofile.dto.NutritionProfileRequest; import com.nutritionplatform.nutritionprofile.service.NutritionProfileService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/nutrition-profile") public class NutritionProfileController { private final NutritionProfileService service; public NutritionProfileController(NutritionProfileService service){this.service=service;} @GetMapping public ResponseEntity<?> get(Authentication a){var p=service.get((UUID)a.getPrincipal());return p==null?ResponseEntity.noContent().build():ResponseEntity.ok(java.util.Map.of("completed",p.complete(),"displayName",p.getDisplayName()));} @PutMapping public ResponseEntity<?> save(Authentication a,@Valid @RequestBody NutritionProfileRequest r){var p=service.save((UUID)a.getPrincipal(),r);return ResponseEntity.ok(java.util.Map.of("completed",p.complete(),"displayName",p.getDisplayName()));} }
